/**
 * Typed id convention for Kiero.
 *
 * Two id families exist:
 *
 * - **Document ids** are generated by Convex for a row of one table. They are
 *   represented as branded strings keyed by the table name
 *   (`TableId<"companies">` is not assignable to `TableId<"tasks">`), so a
 *   mistyped reference is a compile error. The closed `TableIdName` union is
 *   the table inventory owned by the modular schema fragments; a new table is
 *   a coordinated change to this file and its fragment.
 * - **Generated ids** (domain event ids, correlation ids, idempotency keys)
 *   are produced by Kiero code before any row exists. They are branded UUID
 *   values created through `newX` helpers below. Constructing them always
 *   goes through the schema (never a cast), so an invalid value cannot enter.
 *
 * Certified by A3 on 2026-09-09 (docs/implementation/contracts/README.md).
 */

import { Schema } from "effect";

/**
 * The closed table inventory of the modular Convex schema, as a runtime
 * constant. `convex/schema.ts` checks its composition against this list, so
 * a fragment table without an inventory entry (or the reverse) fails loudly.
 */
export const TABLE_ID_NAMES = [
  // access/identity
  "users",
  "sessions",
  // access/identity: Convex Auth provider tables (B1 amendment; the library
  // owns their shape, the identity fragment registers them in the schema)
  "authSessions",
  "authAccounts",
  "authRefreshTokens",
  "authVerificationCodes",
  "authVerifiers",
  "authRateLimits",
  // access/membership
  "companies",
  "memberships",
  "invitations",
  // access/gm
  "gmAccessGrants",
  // projects
  "contacts",
  "contactRoles",
  "projects",
  "projectAliases",
  // sources/accept
  "sources",
  "sourceProjectLinks",
  "extractions",
  "sourceFragments",
  // sources/uploads
  "uploads",
  "attachments",
  "mediaRepresentations",
  // memory/findings
  "findings",
  "findingRevisions",
  "evidenceLinks",
  "findingDependencies",
  "changeSets",
  "publicationGroups",
  "clarifications",
  // memory/extensions
  "extensionDefinitions",
  "extensionVersions",
  "extensionUsage",
  // work
  "tasks",
  "checklistItems",
  "events",
  // platform (durable execution + outbox)
  "processingRuns",
  "processingSteps",
  "processingAttempts",
  "durableJobs",
  "outboxEvents",
  // A3 certification amendment: observable external-effect ledger used by the
  // no-duplicate-effect proof (the echo stand-in for external systems).
  "externalEffects",
  // attention/read-state
  "readStates",
  // attention/preferences
  "notificationPreferences",
  // attention/delivery
  "notificationIntents",
  "pushSubscriptions",
  "notificationAttempts",
  // calendar/connection
  "calendarConnections",
  // calendar/projection
  "calendarCopies",
  "calendarSyncState",
  // operations/exports
  "exports",
  "exportSourceLinks",
  // operations/deletion
  "deletionRecords",
  // operations/backups
  "recoveryManifests",
  // operations/telemetry
  "auditRecords",
  "diagnosticEvents",
  // search
  "searchEntries",
  "searchIndexGenerations",
] as const;

/** The closed table inventory (derived from the runtime constant). */
export type TableIdName = (typeof TABLE_ID_NAMES)[number];

/**
 * The closed set of tables a revision expectation or conflict reference may
 * name. The `satisfies` check ties every member to the live table inventory:
 * renaming or removing one of these tables breaks compilation here instead
 * of silently accepting dead names.
 */
const EXPECTED_RECORD_TABLES = [
  "findings",
  "tasks",
  "checklistItems",
  "events",
  "projects",
  "sources",
  "extensionDefinitions",
  "clarifications",
] as const satisfies readonly TableIdName[];

export const ExpectedRecordTable = Schema.Literals(EXPECTED_RECORD_TABLES);
export type ExpectedRecordTable = Schema.Schema.Type<typeof ExpectedRecordTable>;

/**
 * The branded schema for one table's document ids. Instantiated with a
 * literal table name it yields a nominally distinct string type.
 */
export const tableIdSchema = <T extends TableIdName>(table: T) =>
  Schema.String.pipe(Schema.brand(table));

/** The branded document id type of one table. */
export type TableId<T extends TableIdName> = Schema.Schema.Type<
  ReturnType<typeof tableIdSchema<T>>
>;

/**
 * Normalizes an unknown value into a branded table id without a cast.
 *
 * This checks only that the value is a string; it does NOT prove the id
 * exists in the table or that the string is a well-formed Convex id:
 * Convex generates ids and validates them server-side (`ctx.db.normalizeId`),
 * which is part of the A3 runtime proof. The brand ties the reference to one
 * table so cross-table misuse fails to compile.
 */
export function parseTableId<T extends TableIdName>(
  table: T,
  value: unknown,
): TableId<T> | null {
  const decoded = Schema.decodeUnknownOption(tableIdSchema(table))(value);
  return decoded._tag === "Some" ? decoded.value : null;
}

// Load-bearing document id aliases (English table names; see CONTEXT.md for
// the Polish domain terms these records carry).

export type UserId = TableId<"users">;
export type SessionId = TableId<"sessions">;
export type CompanyId = TableId<"companies">;
export type MembershipId = TableId<"memberships">;
export type InvitationId = TableId<"invitations">;
export type ContactId = TableId<"contacts">;
export type ProjectId = TableId<"projects">;
export type SourceId = TableId<"sources">;
export type UploadId = TableId<"uploads">;
export type AttachmentId = TableId<"attachments">;
export type MediaRepresentationId = TableId<"mediaRepresentations">;
export type ExtractionId = TableId<"extractions">;
export type SourceFragmentId = TableId<"sourceFragments">;
export type FindingId = TableId<"findings">;
export type FindingRevisionId = TableId<"findingRevisions">;
export type ChangeSetId = TableId<"changeSets">;
export type ClarificationId = TableId<"clarifications">;
export type ExtensionDefinitionId = TableId<"extensionDefinitions">;
