// Generated identifiers (created by Kiero code, not by Convex). Each is a
// UUID validated and branded through its own schema; construction always
// decodes through the schema, so a malformed value cannot exist.

/** Id of one emitted domain event (outbox row identity). */
export const EventIdSchema = Schema.String.pipe(
  Schema.check(Schema.isUUID()),
  Schema.brand("EventId"),
);
export type EventId = Schema.Schema.Type<typeof EventIdSchema>;

/** Correlation id threading one user/agent interaction through commands, jobs and events. */
export const CorrelationIdSchema = Schema.String.pipe(
  Schema.check(Schema.isUUID()),
  Schema.brand("CorrelationId"),
);
export type CorrelationId = Schema.Schema.Type<typeof CorrelationIdSchema>;

/** Client-chosen idempotency key for a command; `idem_` + uuid. */
export const IdempotencyKeySchema = Schema.String.pipe(
  Schema.check(Schema.isPattern(/^idem_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/)),
  Schema.brand("IdempotencyKey"),
);
export type IdempotencyKey = Schema.Schema.Type<typeof IdempotencyKeySchema>;

/** Id of a durable job registration; `job_` + uuid. */
export const DurableJobKeySchema = Schema.String.pipe(
  Schema.check(Schema.isPattern(/^job_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/)),
  Schema.brand("DurableJobKey"),
);
export type DurableJobKey = Schema.Schema.Type<typeof DurableJobKeySchema>;

function newGeneratedUuid(): string {
  return crypto.randomUUID();
}

/** Generates a fresh domain event id (decode through the schema, no casts). */
export function newEventId(): EventId {
  return Schema.decodeUnknownSync(EventIdSchema)(newGeneratedUuid());
}

/** Generates a fresh correlation id. */
export function newCorrelationId(): CorrelationId {
  return Schema.decodeUnknownSync(CorrelationIdSchema)(newGeneratedUuid());
}

/** Generates a fresh idempotency key. */
export function newIdempotencyKey(): IdempotencyKey {
  return Schema.decodeUnknownSync(IdempotencyKeySchema)(`idem_${newGeneratedUuid()}`);
}

/** Generates a fresh durable job key. */
export function newDurableJobKey(): DurableJobKey {
  return Schema.decodeUnknownSync(DurableJobKeySchema)(`job_${newGeneratedUuid()}`);
}
